seedCode.App.tsx:
// Import Ionic Angular core components here
import { Component } from '@angular/core';
// Import Capacitor Preferences plugin here
import { Preferences } from '@capacitor/preferences';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [],
  template: '<p>Hello World</p>'
})
export class AppComponent {
  // Add properties here: username, notificationsEnabled, storageResult
  username: string = '';
  notificationsEnabled: boolean = false;
  storageResult: string = '';

  // Create savePreferences method here
  async savePreferences() {
    await Preferences.set({
      key: 'username',
      value: this.username
    });
    await Preferences.set({
      key: 'notificationsEnabled',
      value: this.notificationsEnabled.toString()
    });
    this.storageResult = 'Preferences saved!';
  }

  // Create loadPreferences method here
}

steps.analogousExample:
// Example async method to clear preferences
async clearPreferences() {
  await Preferences.clear();
  this.storageResult = 'Preferences cleared!';
}

